function PanelHeader({title,subtitle,action,onAction}){return <div className="panel-header"><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div>{action&&<button className="text-action" onClick={onAction}>{action}<ArrowRight size={14}/></button>}</div>}
