  const reload=async({quiet=false}={})=>{if(!isSupabaseConfigured||!user){if(!quiet){setError('Supabase session is not ready. Sign in again and retry.');notify('Unable to refresh: Supabase session is not ready.')}return}setRefreshing(true);setError('');try{const mine=await loadMyClasses(user,'teacher');setClasses(mine);if(!mine.length){setPending([]);if(!quiet)notify('Refreshed. No classes are assigned to this teacher account yet.');return}const {data,error:requestError}=await supabase.from('class_memberships').select('class_id,student_id,registration_number,class:classes(name,code),student:profiles!class_memberships_student_id_fkey(full_name,email,campus_id)').eq('status','pending').in('class_id',mine.map(c=>c.id));if(requestError)throw requestError;setPending(data||[]);if(!quiet)notify(`Classes refreshed · ${mine.length} class${mine.length===1?'':'es'} found.`)}catch(err){setError(err.message);if(!quiet)notify(`Could not refresh classes: ${err.message}`)}finally{setRefreshing(false)}};useEffect(()=>{reload({quiet:true})},[user?.id]);
  const decide=async x=>{try{await reviewMembership(x.class_id,x.student_id,user.id,true);notify('Student added to the class.');await reload({quiet:true})}catch(e){setError(e.message)}};
