  const submit=async(item)=>{try{await saveSubmission(user,item.id,files[item.id]);notify('Assignment submitted.');await reload()}catch(e){notify(e.message)}};
  const openResource=async(path,url)=>{try{if(url){window.open(url,'_blank','noopener,noreferrer');return}if(path){window.open(await downloadMaterial(path),'_blank','noopener,noreferrer')}}catch(e){notify(e.message)}};
