  return <><PageHeading eyebrow="MAKE TIME FOR WHAT MATTERS" title="Assignments" subtitle="A clear view of what’s due and what you’ve already done."/><div className="assignment-summary"><div><span className="assignment-number">{isSupabaseConfigured?items.filter(x=>!x.submissions?.length).length:'03'}</span><span>To finish</span></div><div><span className="assignment-number">{isSupabaseConfigured?items.filter(x=>x.due_at&&new Date(x.due_at)<new Date(Date.now()+7*864e5)).length:'01'}</span><span>Due this week</span></div><div><span className="assignment-number">{isSupabaseConfigured?items.filter(x=>x.submissions?.length).length:'08'}</span><span>Submitted</span></div></div><section className="panel table-panel"><PanelHeader title="Your assignments" subtitle={loading?'Loading…':'Classwork and due dates'}/>{error&&<p className="form-error">{error}</p>}{isSupabaseConfigured&&!loading&&!items.length?<div className="empty-state"><ClipboardCheck size={24}/><b>No assignments yet</b><span>New work from your teachers will appear here.</span></div>:<DataTable headers={['ASSIGNMENT','CLASS','DUE DATE','YOUR SUBMISSION']} rows={rows}/>}</section></>;
