function StudentCalendar({user}){
 const [events,setEvents]=useState([]),[notices,setNotices]=useState([]),[error,setError]=useState(''),[loading,setLoading]=useState(true);
 useEffect(()=>{let live=true;(async()=>{try{const {data:enrollment,error:enrollmentError}=await supabase.from('campus_enrollments').select('campus_id').eq('user_id',user.id).eq('status','active').maybeSingle();if(enrollmentError)throw enrollmentError;if(!enrollment){if(live){setEvents([]);setNotices([])}return}
 const [eventResult,noticeResult]=await Promise.all([supabase.from('events').select('id,title,description,starts_at,ends_at,location').eq('campus_id',enrollment.campus_id).gte('starts_at',new Date().toISOString()).order('starts_at').limit(100),supabase.from('notices').select('id,title,body,audience_role,published_at,expires_at').eq('campus_id',enrollment.campus_id).order('published_at',{ascending:false}).limit(100)]);if(eventResult.error)throw eventResult.error;if(noticeResult.error)throw noticeResult.error;if(live){setEvents(eventResult.data||[]);setNotices(noticeResult.data||[])}}
 catch(e){if(live)setError(e.message)}finally{if(live)setLoading(false)}})();return()=>{live=false}},[user?.id]);
 return <><PageHeading eyebrow="WHAT’S HAPPENING" title="Calendar & notices" subtitle="Campus events and announcements shared with you."/>{error&&<p className="form-error">{error}</p>}<div className="dashboard-columns"><section className="panel"><PanelHeader title="Coming up" subtitle={loading?'Loading campus schedule…':events.length+' upcoming event'+(events.length===1?'':'s')}/>{events.length?events.map(event=><div className="event-row" key={event.id}><div className="event-date"><b>{new Date(event.starts_at).toLocaleDateString('en-IN',{day:'2-digit'})}</b><span>{new Date(event.starts_at).toLocaleDateString('en-IN',{month:'short'}).toUpperCase()}</span></div><div><b>{event.title}</b><span>{new Date(event.starts_at).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'})}{event.location?' · '+event.location:''}</span></div></div>):!loading&&<div className="empty-state"><CalendarDays size={22}/><span>No upcoming campus events.</span></div>}</section><section className="panel"><PanelHeader title="Campus notices" subtitle="Latest messages for your campus"/>{notices.length?notices.map(notice=><div className="notice-item" key={notice.id}><Tag tone={notice.audience_role==='student'?'blue':'violet'}>{notice.audience_role?notice.audience_role.toUpperCase():'CAMPUS UPDATE'}</Tag><h3>{notice.title}</h3><p>{notice.body}</p><span>{new Date(notice.published_at).toLocaleDateString('en-IN',{dateStyle:'medium'})}</span></div>):!loading&&<div className="empty-state"><Bell size={22}/><span>No campus notices yet.</span></div>}</section></div></>;
}

