 useEffect(()=>{if(branchId)listSubjects(branchId).then(s=>{setSubjects(s);setSubjectId(current=>s.some(x=>x.id===current)?current:s[0]?.id||'')}).catch(e=>setError(e.message))},[branchId]);
 useEffect(()=>{if(classId&&!classes.some(c=>c.id===classId&&c.branch_id===branchId))setClassId('')},[branchId,classes]);
 const assign=async e=>{e.preventDefault();setBusy(true);setError('');const form=e.currentTarget,f=new FormData(form);try{const linked=await assignBranchTeacher(user,{branch_id:f.get('branch_id'),subject_id:f.get('subject_id'),teacher_id:f.get('teacher_id')});notify(linked?`Teacher assigned and linked to ${linked} matching class${linked===1?'':'es'}.`:'Branch assignment saved. No existing class uses this branch subject yet; create/link the subject on a class or run Sync existing assignments later.');await reload()}catch(e){setError(e.message);notify(`Teacher assignment failed: ${e.message}`)}finally{setBusy(false)}};
