function CampusRoutines(){
 const[rows,setRows]=useState([]),[error,setError]=useState(''),[search,setSearch]=useState('');
 useEffect(()=>{(async()=>{try{const {data:routines,error}=await supabase.from('class_routines').select('id,teacher_id,weekday,starts_at,ends_at,room,class_id,class_subject_id,class:classes(code,name,branch:branches(name,code)),teacher:profiles!class_routines_teacher_id_fkey(full_name,email)').order('weekday').order('starts_at');if(error)throw error;const ids=[...new Set((routines||[]).map(x=>x.class_subject_id))];const {data:links,error:linkError}=ids.length?await supabase.from('class_subjects').select('id,subject:subjects(name,code)').in('id',ids):{data:[],error:null};if(linkError)throw linkError;const byId=new Map((links||[]).map(x=>[x.id,x.subject]));setRows((routines||[]).map(x=>({...x,subject:byId.get(x.class_subject_id)})))}catch(e){setError(e.message)}})()},[]);
 const days=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
 const reports=rows.map(row=>({...row,conflict:rows.some(other=>other.id!==row.id&&other.weekday===row.weekday&&row.starts_at<other.ends_at&&row.ends_at>other.starts_at&&(row.teacher_id===other.teacher_id||(row.room&&row.room.toLowerCase()===(other.room||'').toLowerCase())))}));
 const visible=reports.filter(x=>[x.teacher?.full_name,x.class?.name,x.class?.code,x.subject?.name,x.room].some(v=>(v||'').toLowerCase().includes(search.toLowerCase())));
 const exportRows=()=>downloadCsv('campus-routines.csv',['Day','Start','End','Branch','Class','Subject','Teacher','Room','Conflict'],visible.map(x=>[days[x.weekday],x.starts_at,x.ends_at,x.class?.branch?.name,(x.class?.code||'')+' · '+(x.class?.name||''),x.subject?.name,x.teacher?.full_name,x.room,x.conflict?'Check schedule':'']));
 return <><PageHeading eyebrow="CAMPUS OPERATIONS" title="Class routines" subtitle="View the weekly timetable and catch teacher or room overlaps." action={<button className="btn btn-secondary" onClick={exportRows}><ArrowDownToLine size={15}/> Export CSV</button>}/>{error&&<p className="form-error">{error}</p>}<section className="panel table-panel"><div className="directory-tools"><label className="search-field"><Search size={16}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search teacher, class, subject or room"/></label><span>{reports.filter(x=>x.conflict).length} overlapping entries</span></div><DataTable headers={['DAY','TIME','BRANCH · CLASS','SUBJECT','TEACHER','ROOM','SCHEDULE']} rows={visible.map(x=>[days[x.weekday],x.starts_at.slice(0,5)+'–'+x.ends_at.slice(0,5),(x.class?.branch?.code||'')+' · '+(x.class?.code||'')+' '+(x.class?.name||''),x.subject?.name||'—',x.teacher?.full_name||x.teacher?.email||'—',x.room||'—',x.conflict?<Tag tone="amber">Check overlap</Tag>:<Tag tone="green">Clear</Tag>])}/></section></>;
}

function DataTable({headers,rows}){return <div className="table-scroll"><table className="data-table"><thead><tr>{headers.map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{rows.map((row,i)=><tr key={i}>{row.map((cell,j)=><td key={j}>{cell}</td>)}</tr>)}</tbody></table></div>}
async function registerByRole(role,email,password,metadata){
  if(role==='admin') return supabase.auth.signUp({email,password,options:{emailRedirectTo:window.location.origin,data:metadata}});
  const {data,error}=await supabase.functions.invoke('campus-register',{body:{...metadata,role,email,password}});
  if(error){
    let message=error.message||'Campus registration failed.';
    const response=error.context;
    if(response&&typeof response.clone==='function'){
      try{const payload=await response.clone().json();if(typeof payload?.error==='string')message=payload.error;else if(response.status)message+=` (HTTP ${response.status})`}
      catch{if(response.status)message+=` (HTTP ${response.status})`}
    }
    return {data:null,error:new Error(message)};
  }
  if(data?.error) return {data:null,error:new Error(data.error)};
  return {data:{session:null,user:{id:data.user_id}},error:null,message:data.message};
}

function AuthDialog({mode,setMode,role,setRole,user,close,notify,setUser,setProfile,standalone=false}){
  const [busy,setBusy]=useState(false);const [resendBusy,setResendBusy]=useState(false);const [resendEmail,setResendEmail]=useState('');const [error,setError]=useState('');const [campusBranches,setCampusBranches]=useState([]);const [campusSessions,setCampusSessions]=useState([]);const [campusPairs,setCampusPairs]=useState([]);const [pickedBranch,setPickedBranch]=useState('');const [pickedSession,setPickedSession]=useState('');const [campusChecked,setCampusChecked]=useState(false);
  const findCampus=async e=>{const code=e.currentTarget.value.trim().toUpperCase();setCampusChecked(false);setCampusBranches([]);setCampusSessions([]);if(!code||!isSupabaseConfigured)return;const {data:campus,error}=await supabase.from('campuses').select('id,campus_code,name').eq('campus_code',code).eq('is_active',true).maybeSingle();if(error){setError(error.message);return}if(!campus){setError('Campus ID not found. Check with your campus admin.');return}const [branches,sessions,pairs]=await Promise.all([supabase.from('branches').select('id,name,code').eq('campus_id',campus.id).eq('is_active',true).order('name'),supabase.from('academic_sessions').select('id,name').eq('campus_id',campus.id).eq('is_active',true).order('name'),supabase.from('session_branches').select('branch_id,session_id').eq('campus_id',campus.id)]);if(branches.error||sessions.error||pairs.error){setError(branches.error?.message||sessions.error?.message||pairs.error?.message);return}setCampusBranches(branches.data||[]);setCampusSessions(sessions.data||[]);setCampusPairs(pairs.data||[]);setPickedSession(sessions.data?.[0]?.id||'');setPickedBranch('');setCampusChecked(true);setError('')};
  const studentBranches=campusBranches.filter(b=>campusPairs.some(p=>p.branch_id===b.id&&p.session_id===pickedSession));
  const studentSessions=campusSessions.filter(x=>campusPairs.some(p=>p.session_id===x.id&&(!pickedBranch||p.branch_id===pickedBranch)));
  const resendConfirmation=async()=>{if(!resendEmail)return;setResendBusy(true);const {error}=await supabase.auth.resend({type:'signup',email:resendEmail,options:{emailRedirectTo:window.location.origin}});setError(error?error.message:'A fresh confirmation email was sent. Use the newest email link.');setResendBusy(false)};
  const submit=async e=>{e.preventDefault();setError('');setBusy(true);const form=new FormData(e.currentTarget);const email=form.get('email'),password=form.get('password'),full_name=form.get('name');setResendEmail(email?.toString()||'');
    if(!isSupabaseConfigured){setBusy(false);close();notify('Fill in the Supabase values in the project .env file, then restart the app to activate sign in.');return}
    try{if(mode==='register'){const campusCode=form.get('campus_code')?.toString().trim().toUpperCase();if(role==='admin'){if(!form.get('campus_name')?.toString().trim())throw new Error('Enter the name of the campus you are creating.')}else{if(!campusCode)throw new Error('Enter the Campus ID provided by your campus.');if(!campusChecked)throw new Error('Check the Campus ID before continuing.');if(role==='student'&&(!form.get('branch_id')||!form.get('session_id')||!String(form.get('college_registration_number')||'').trim()))throw new Error('Enter your college registration number and choose an academic session and branch.')}const {data,error}=await registerByRole(role,email,password,{full_name,requested_role:role,mobile:form.get('phone')||null,gender:form.get('gender')||null,campus_code:campusCode,campus_name:form.get('campus_name')||null,campus_address:form.get('campus_address')||null,branch_id:form.get('branch_id')||null,session_id:form.get('session_id')||null,college_registration_number:form.get('college_registration_number')||null,department:form.get('course')||null,address:form.get('address')||null,guardian_name:form.get('guardian_name')||null,guardian_mobile:form.get('guardian_mobile')||null,emergency_contact_name:form.get('emergency_contact_name')||null,emergency_contact_mobile:form.get('emergency_contact_mobile')||null});if(error)throw error;if(data.session){notify(role==='admin'?'Campus created. Check your email, then sign in and add branches.':'Registration sent. Your campus admin must approve your account.');close()}else{setMode('login');setError(role==='admin'?'Campus created. Confirm your email once, then sign in.':role==='teacher'?'Account created. Sign in after the campus admin approves your teacher profile.':'Account created. Sign in; your campus enrollment will need approval before you can access class study data.')}}else{const {data,error}=await supabase.auth.signInWithPassword({email,password});if(error)throw error;const {data:profile,error:profileError}=await supabase.from('profiles').select('role,account_status,full_name,email,mobile,gender,address,department,campus_id').eq('id',data.user.id).single();if(profileError||!profile)throw new Error('Campus profile is unavailable. Ask your campus administrator to check your account.');if(profile.role!==role){await supabase.auth.signOut();throw new Error(`This account belongs to the ${roles[profile.role]||'campus'} login. Choose the matching role and try again.`)}if(profile.account_status==='suspended'){await supabase.auth.signOut();throw new Error('This campus account is paused. Contact your campus administrator.')}setProfile({...profile,college_registration_number:data.user.user_metadata?.college_registration_number||null});setRole(profile.role);localStorage.setItem('mc-role',profile.role);setUser(data.user);notify(profile.account_status==='pending'?'Signed in. Your campus account is waiting for admin verification.':'Welcome back.');close()}}catch(err){setError(err.message||'Could not complete that request.')}finally{setBusy(false)}
  };
  return <div className="modal-layer" onMouseDown={e=>{if(e.target===e.currentTarget&&mode==='login')close()}}><section className="auth-modal" role="dialog" aria-modal="true" aria-labelledby="auth-title">{!standalone&&<button className="modal-x" onClick={close} aria-label="Close"><X size={19}/></button>}<div className="modal-brand"><span className="brand-symbol"><GraduationCap size={20}/></span><b>mastercampus</b></div><h2 id="auth-title">{user?'Your campus account':mode==='register'?'A fresh start, together.':'Welcome back.'}</h2><p>{user?'Your account is connected to Master Campus.':mode==='register'?'Create your account and find your place on campus.':'Sign in to pick up where you left off.'}</p>{user?<button className="btn btn-primary btn-wide" onClick={close}>Done</button>:<><div className="auth-tabs"><button className={mode==='login'?'active':''} onClick={()=>{setError('');setMode('login')}}>Sign in</button><button className={mode==='register'?'active':''} onClick={()=>{setError('');if(role==='admin'||role==='platform_admin')setRole('student');setMode('register')}}>Create account</button></div><form onSubmit={submit}><div className="role-picker-label">{mode==='login'?'Choose your login':'Create an account as'}</div><div className="auth-role-grid">{(mode==='login'?Object.entries(roles):Object.entries(roles).filter(([key])=>key!=='platform_admin')).map(([key,label])=><button type="button" key={key} className={`auth-role-option ${role===key?'active':''}`} aria-pressed={role===key} onClick={()=>setRole(key)}>{key==='student'?'Student':key==='teacher'?'Teacher':key==='admin'?'Campus Admin':'Platform Admin'}</button>)}</div>{mode==='register'&&<><label>Full name<input name="name" autoComplete="name" required placeholder="Your full name"/></label><div className="form-row"><label>Mobile number<input name="phone" inputMode="tel" placeholder="+91"/></label><label>Gender<select name="gender"><option value="">Choose…</option><option>Woman</option><option>Man</option><option>Non-binary</option><option>Prefer not to say</option></select></label></div>{role==='admin'?<><label>Campus name<input name="campus_name" required placeholder="e.g. Master Campus Institute"/></label><label>Campus address<input name="campus_address" placeholder="City, state"/></label><p className="form-note"><Building2 size={14}/> Your campus will be created with a unique Campus ID. You can then add branches and verify teachers and students.</p></>:<><label>Campus ID<input name="campus_code" required placeholder="e.g. MC-7FA93C21" onBlur={findCampus}/></label>{campusChecked&&<>{role==='student'?<><p className="form-note"><ShieldCheck size={14}/> Campus ID verified. Choose your branch and academic session.</p><div className="form-row"><label>Academic session<select name="session_id" required value={pickedSession} onChange={e=>{setPickedSession(e.target.value);setPickedBranch('')}}><option value="">Select session</option>{studentSessions.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label><label>Branch<select name="branch_id" required value={pickedBranch} onChange={e=>setPickedBranch(e.target.value)}><option value="">Select branch</option>{studentBranches.map(b=><option key={b.id} value={b.id}>{b.code} · {b.name}</option>)}</select></label></div><label>College registration number<input name="college_registration_number" required maxLength="80" autoComplete="off" placeholder="Enter the number issued by your college"/></label><p className="form-note"><ShieldCheck size={14}/> This number must be unique in your campus. The app will also assign an internal code after registration.</p><details className="optional-details"><summary>Optional: parent and emergency contacts</summary><div className="form-row"><label>Parent / guardian name<input name="guardian_name" autoComplete="name"/></label><label>Parent / guardian phone<input name="guardian_mobile" inputMode="tel"/></label></div><div className="form-row"><label>Emergency contact name<input name="emergency_contact_name"/></label><label>Emergency contact phone<input name="emergency_contact_mobile" inputMode="tel"/></label></div></details></>:<p className="form-note"><ShieldCheck size={14}/> Campus ID verified. A campus admin will verify your teacher account.</p>}</>}{role==='teacher'&&<label>Address<input name="address" autoComplete="street-address" placeholder="Residential address"/></label>}</>}</>}<label>Email address<input name="email" type="email" autoComplete="email" required placeholder="you@campus.edu" onChange={e=>setResendEmail(e.target.value)}/></label><label>Password<input name="password" type="password" autoComplete={mode==='register'?'new-password':'current-password'} minLength="8" required placeholder="At least 8 characters"/></label>{error&&<p className="form-error">{error}</p>}{mode==='login'&&error.toLowerCase().includes('email not confirmed')&&<button type="button" className="text-action" disabled={resendBusy||!resendEmail} onClick={resendConfirmation}>{resendBusy?'Sending…':'Resend confirmation email'}</button>}<button className="btn btn-primary btn-wide" disabled={busy}>{busy?'One moment…':mode==='register'?'Create my account':'Sign in'} <ArrowRight size={15}/></button></form><div className="auth-secure"><LockKeyhole size={12}/> Your account is protected by campus sign-in</div></>}</section></div>
}
function QuizDialog({ready,setReady,close,notify,user}){
  const [options,setOptions]=useState([]),[sourceKey,setSourceKey]=useState(''),[count,setCount]=useState(5),[difficulty,setDifficulty]=useState('mixed');
  const [busy,setBusy]=useState(false),[error,setError]=useState(''),[quiz,setQuiz]=useState(null),[answers,setAnswers]=useState({}),[score,setScore]=useState(null);
  useEffect(()=>{let mounted=true;(async()=>{if(!isSupabaseConfigured||!user)return;try{const classes=await loadMyClasses(user,'student'),ids=classes.map(c=>c.id);if(!ids.length){if(mounted)setOptions([]);return}const [m,a,u]=await Promise.all([supabase.from('materials').select('id,class_id,title,description,content_text').in('class_id',ids).order('created_at',{ascending:false}),supabase.from('assignments').select('id,class_id,title,description').in('class_id',ids).order('due_at',{ascending:true}),supabase.from('syllabus_units').select('id,class_id,title,description').in('class_id',ids).order('sort_order')]);for(const r of [m,a,u])if(r.error)throw r.error;const choices=[...(m.data||[]).map(x=>({...x,kind:'material'})),...(a.data||[]).map(x=>({...x,kind:'assignment'})),...(u.data||[]).map(x=>({...x,kind:'syllabus'}))].filter(x=>(x.content_text||x.description||'').length>30);if(mounted){setOptions(choices);setSourceKey(choices[0]?`${choices[0].kind}:${choices[0].id}`:'')}}catch(err){if(mounted)setError(err.message)}})();return()=>{mounted=false}},[user]);
  const generate=async()=>{setError('');setBusy(true);try{if(!isSupabaseConfigured||!user)throw new Error('Sign in to your campus account and connect Supabase before generating a course quiz.');const source=options.find(x=>`${x.kind}:${x.id}`===sourceKey);if(!source)throw new Error('No class source with lesson notes is available yet. Ask your teacher to add source notes to the material, assignment, or syllabus.');const {data:payload,error}=await supabase.functions.invoke('campus-ai',{body:{action:'quiz',sourceKind:source.kind,sourceId:source.id,count:Number(count),difficulty}});if(error)throw error;if(payload?.error)throw new Error(payload.error);setQuiz(payload);setAnswers({});setScore(null);setReady(true)}catch(err){setError(err.message)}finally{setBusy(false)}};
  const finish=async()=>{if(!quiz)return;const total=quiz.questions.length,correct=quiz.questions.reduce((n,q,i)=>n+(Number(answers[i])===q.answer_index?1:0),0);setScore({correct,total});if(isSupabaseConfigured){const {error:saveError}=await supabase.from('generated_quizzes').update({score:correct,completed_at:new Date().toISOString()}).eq('id',quiz.id);if(saveError)setError(`Score could not be saved: ${saveError.message}`)}};
  return <div className="modal-layer" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><section className="auth-modal quiz-modal" role="dialog" aria-modal="true" aria-labelledby="quiz-title"><button className="modal-x" onClick={close} aria-label="Close"><X size={19}/></button><div className="quiz-modal-icon"><Sparkles size={21}/></div><span className="eyebrow">A LITTLE PRACTICE GOES A LONG WAY</span><h2 id="quiz-title">{score?'Nice work.':quiz?'Your practice quiz.':'Build your study quiz.'}</h2><p>{score?`You got ${score.correct} out of ${score.total} questions right.`:quiz?'Choose your answer for each question. Your result will be saved to your learning history.':'Choose a course source. The quiz is generated from your teacher’s saved notes.'}</p>{!quiz&&<><label>Course material<select value={sourceKey} onChange={e=>setSourceKey(e.target.value)} disabled={!options.length}><option value="">{options.length?'Choose a study source':'No class notes available yet'}</option>{options.map(x=><option key={`${x.kind}:${x.id}`} value={`${x.kind}:${x.id}`}>{x.title} · {x.kind}</option>)}</select></label><div className="form-row"><label>Question count<select value={count} onChange={e=>setCount(e.target.value)}><option value="5">5 questions</option><option value="10">10 questions</option><option value="15">15 questions</option></select></label><label>Difficulty<select value={difficulty} onChange={e=>setDifficulty(e.target.value)}><option value="mixed">Mixed review</option><option value="warmup">Quick warm-up</option><option value="challenge">Challenge me</option></select></label></div></>}{quiz&&!score&&<div className="quiz-question-list">{quiz.questions.map((q,i)=><article className="quiz-question" key={i}><b>{i+1}. {q.question}</b>{q.options.map((option,j)=><label className={`quiz-option ${answers[i]===j?'quiz-option-selected':''}`} key={j}><input type="radio" name={`q${i}`} checked={answers[i]===j} onChange={()=>setAnswers({...answers,[i]:j})}/>{option}</label>)}</article>)}</div>}{score&&<div className="quiz-review">{quiz.questions.map((q,i)=><div key={i}><b>{i+1}. {answers[i]===q.answer_index?'Correct':'Review'} · {q.options[q.answer_index]}</b><span>{q.explanation}</span></div>)}</div>}{error&&<p className="form-error">{error}</p>}{!quiz?<button className="btn btn-primary btn-wide" disabled={busy||!sourceKey} onClick={generate}>{busy?'Building your quiz…':'Generate my quiz'} <Sparkles size={15}/></button>:!score?<button className="btn btn-primary btn-wide" disabled={Object.keys(answers).length<quiz.questions.length} onClick={finish}>Check my answers <Check size={15}/></button>:<button className="btn btn-primary btn-wide" onClick={close}>Done <Check size={15}/></button>}<div className="auth-secure"><LockKeyhole size={12}/> Quiz questions are generated from your selected class notes</div></section></div>
}

